import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for OptionBuilder.withType(Class)
 */
@SuppressWarnings("deprecation")
public class OptionBuilderWithTypeTest {

    private Field typeField;
    private Field instanceField;
    private Method resetMethod;

    @BeforeEach
    public void setUp() throws Exception {
        // access private static field 'type'
        typeField = OptionBuilder.class.getDeclaredField("type");
        typeField.setAccessible(true);

        // access private static final field 'INSTANCE'
        instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);

        // access private static method 'reset' to clear static state between tests
        resetMethod = OptionBuilder.class.getDeclaredMethod("reset");
        resetMethod.setAccessible(true);

        // ensure a clean start
        resetMethod.invoke(null);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // restore default state after each test
        resetMethod.invoke(null);
    }

    @Test
    public void testWithTypeSetsTypeToGivenClass() throws Exception {
        // choose a class to set
        Class<?> expected = Integer.class;

        // call the focal method
        OptionBuilder returned = OptionBuilder.withType(expected);

        // verify returned instance is the same as the private INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withType should return the singleton INSTANCE");

        // verify the private static field 'type' was updated
        Object actualType = typeField.get(null);
        assertSame(expected, actualType, "type field should be set to the provided class");
    }

    @Test
    public void testWithTypeSetsTypeToNull() throws Exception {
        // first set to a concrete class
        OptionBuilder.withType(String.class);
        assertSame(String.class, typeField.get(null), "precondition: type should be String.class");

        // now set to null
        OptionBuilder returned = OptionBuilder.withType(null);

        // verify returned instance is the same as INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withType should return the singleton INSTANCE even when setting null");

        // verify the private static field 'type' is null
        Object actualType = typeField.get(null);
        assertNull(actualType, "type field should be null after setting null");
    }
}

